import sailpoint.api.Terminator;
import sailpoint.object.Application;
import sailpoint.object.Bundle;
import sailpoint.object.CertificationDefinition;
import sailpoint.object.CorrelationConfig;
import sailpoint.object.EmailTemplate;
import sailpoint.object.Identity;
import sailpoint.object.IdentityTrigger;
import sailpoint.object.PasswordPolicy;
import sailpoint.object.Policy;
import sailpoint.object.QueryOptions;
import sailpoint.object.QuickLink;
import sailpoint.object.Rule;
import sailpoint.object.SailPointObject;
import sailpoint.object.TaskDefinition;
import sailpoint.object.TaskResult;
import sailpoint.object.Workflow;
import sailpoint.tools.Util;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Set;

Terminator terminator = new Terminator(context);
StringBuilder log = new StringBuilder();
int deleted = 0;

Set keepRules = new HashSet();
keepRules.add("MNB-Rule-Hello-World");

boolean isMnbName(String name) {
  return name != null && name.startsWith("MNB-");
}

boolean isMnbTaskName(String name) {
  if (name == null) return false;
  if (name.startsWith("MNB-")) return true;
  if (name.indexOf("MNB") >= 0) return true;
  if (name.startsWith("Aggregate MNB") || name.startsWith("Refresh MNB")) return true;
  return false;
}

void delByName(Class clazz, String name) {
  Object o = context.getObjectByName(clazz, name);
  if (o != null) {
    terminator.deleteObject(o);
    deleted++;
    log.append("DEL ").append(clazz.getSimpleName()).append(" ").append(name).append("\n");
  }
}

void delMnbByClass(Class clazz, boolean taskStyle) {
  QueryOptions qo = new QueryOptions();
  Iterator it = context.search(clazz, qo);
  List names = new ArrayList();
  while (it.hasNext()) {
    Object row = it.next();
    SailPointObject obj = null;
    if (row instanceof SailPointObject) {
      obj = (SailPointObject) row;
    } else if (row instanceof Object[]) {
      Object[] arr = (Object[]) row;
      if (arr.length > 0 && arr[0] instanceof SailPointObject) {
        obj = (SailPointObject) arr[0];
      }
    }
    if (obj == null) continue;
    String n = obj.getName();
    if (clazz == Rule.class && keepRules.contains(n)) continue;
    boolean match = taskStyle ? isMnbTaskName(n) : isMnbName(n);
    if (match) names.add(n);
  }
  Util.flushIterator(it);
  for (Object n : names) {
    delByName(clazz, (String) n);
  }
  log.append("SCAN ").append(clazz.getSimpleName()).append(" mnbCount=").append(names.size()).append("\n");
}

// Identities first (clears Links to apps)
QueryOptions qo = new QueryOptions();
Iterator it = context.search(Identity.class, qo);
List toKill = new ArrayList();
while (it.hasNext()) {
  Identity id = (Identity) it.next();
  if (id != null && !"spadmin".equals(id.getName())) {
    toKill.add(id.getName());
  }
}
Util.flushIterator(it);
for (Object n : toKill) {
  Identity id = context.getObjectByName(Identity.class, (String) n);
  if (id != null) {
    terminator.deleteObject(id);
    deleted++;
  }
}
log.append("DEL Identity count=").append(toKill.size()).append(" (kept spadmin)\n");

delMnbByClass(Application.class, false);
delMnbByClass(TaskDefinition.class, true);
delMnbByClass(Bundle.class, false);
delMnbByClass(Workflow.class, false);
delMnbByClass(Rule.class, false);
delMnbByClass(Policy.class, false);
delMnbByClass(EmailTemplate.class, false);
delMnbByClass(CorrelationConfig.class, false);
delMnbByClass(IdentityTrigger.class, false);
delMnbByClass(QuickLink.class, false);
delMnbByClass(CertificationDefinition.class, false);
delMnbByClass(PasswordPolicy.class, false);

// Best-effort: drop TaskResults whose names mention MNB / Aggregate MNB
QueryOptions tq = new QueryOptions();
Iterator trIt = context.search(TaskResult.class, tq);
List trKill = new ArrayList();
while (trIt.hasNext()) {
  TaskResult tr = (TaskResult) trIt.next();
  if (tr == null || tr.getName() == null) continue;
  String tn = tr.getName();
  if (tn.indexOf("MNB") >= 0 || tn.indexOf("Aggregate MNB") >= 0 || tn.indexOf("Refresh MNB") >= 0) {
    trKill.add(tr.getId());
  }
}
Util.flushIterator(trIt);
for (Object id : trKill) {
  TaskResult tr = context.getObject(TaskResult.class, (String) id);
  if (tr != null) {
    terminator.deleteObject(tr);
    deleted++;
  }
}
log.append("DEL TaskResult MNB-ish count=").append(trKill.size()).append("\n");

context.commitTransaction();
return "OK wiped deletedOps≈" + deleted + "\n" + log.toString();
